add('application-run-scope.test.ts',"describe('host-owned per-application runtime authority and complete selected dependency protection',()=>{",'''
 it('holds only independent roots with explicit schema2 and gives zero application tools while both packages and the app bridge are unavailable',async()=>{
  const before=f.sqlite.prepare('SELECT snapshot_json FROM capability_session_snapshots').get(),refs=f.sqlite.prepare('SELECT * FROM capability_session_refs ORDER BY ref_id').all();for(const p of f.snapshot.packages)f.sqlite.prepare("UPDATE capability_resources SET state='recovery-required',integrity='invalid' WHERE resource_id IN (?,?)").run('app:'+p.packageHash,'runtime:'+p.runtimeHash);
  run=await f.runs.reserveIndependent({taskId:f.snapshot.taskId,snapshotHash:f.session.pointer.snapshotHash,bindings:[]});await activate();expect(f.runs.assertActive(run.runId).applicationScope).toEqual([]);const table=await service.list(run.runId);expect(table.tools).toEqual([]);expect(table.unavailable.map(p=>p.appId).sort()).toEqual(['mail','zentao']);for(const p of f.snapshot.packages)expect(await service.call(run.runId,randomUUID(),query(p.appId))).toMatchObject({status:'error',error:{code:'CAPABILITY_UNAVAILABLE'}});expect(calls).toBe(0);
  const scope=readApplicationRunScope(f.store,run.runId,f.snapshot)!;expect(scope).toMatchObject({schema:2,mode:'independent-capabilities',applications:[]});expect(scope.roots.some(r=>r.refKind==='application-package'||r.refKind==='runtime')).toBe(false);expect(f.sqlite.prepare('SELECT snapshot_json FROM capability_session_snapshots').get()).toEqual(before);expect(f.sqlite.prepare('SELECT * FROM capability_session_refs ORDER BY ref_id').all()).toEqual(refs);
  f.setAllowed(false);expect(()=>f.runs.assertActive(run!.runId)).toThrow();f.setAllowed(true);expect(f.runs.assertActive(run.runId).applicationScope).toEqual([]);
 });
 it('refuses an erased independent receipt and a rehashed old schema1 empty grant instead of inferring full S',async()=>{
  run=await f.runs.reserveIndependent({taskId:f.snapshot.taskId,snapshotHash:f.session.pointer.snapshotHash,bindings:[]});await activate();const row=receipt();try{f.sqlite.prepare('DELETE FROM capability_resource_operations WHERE operation_id=?').run(key());expect(()=>f.runs.assertActive(run!.runId)).toThrow('无法核验');expect(await service.call(run.runId,randomUUID(),query())).toMatchObject({status:'error'});restore(row);const value=JSON.parse(row.plan_json as string),{evidenceHash:_,mode:__,...payload}=value;payload.schema=1;f.sqlite.prepare('UPDATE capability_resource_operations SET plan_json=? WHERE operation_id=?').run(canonicalJson({...payload,evidenceHash:digest(canonicalJson(payload))}),key());expect(()=>readApplicationRunScope(f.store,run!.runId,f.snapshot)).toThrow('无法核验');expect(f.runs.get(run.runId).state).toBe('active');expect(calls).toBe(0);}finally{restore(row);}
 });
 it('still refuses a missing independent shared dependency before recording any zero-application run',async()=>{
  f.sqlite.prepare("UPDATE capability_resources SET state='deleting' WHERE resource_id=?").run(f.child.resourceId);await expect(f.runs.reserveIndependent({taskId:f.snapshot.taskId,snapshotHash:f.session.pointer.snapshotHash,bindings:[]})).rejects.toThrow('未就绪');expect(f.sqlite.prepare('SELECT * FROM capability_runs').all()).toEqual([]);
 });
''')
add('claude-delivery.test.ts',"describe('real canonical Claude delivery and independent physical root occupancy',()=>{",'''
 it('delivers only original standards through an explicit independent slot and run without granting either original application',async()=>{
  const before=await f.sessions.references(f.snapshot.taskId);for(const p of f.snapshot.packages){rmSync(join(f.store.root,f.store.get('app:'+p.packageHash).relativePath),{recursive:true});f.sqlite.prepare("UPDATE capability_resources SET state='recovery-required',integrity='invalid' WHERE resource_id=?").run('app:'+p.packageHash);}
  await expect(c.prepare(f.snapshot.taskId,[])).rejects.toMatchObject({code:'INVALID_INPUT'});const token=await c.prepareIndependent(f.snapshot.taskId),run=await f.runs.reserveIndependent({taskId:f.snapshot.taskId,snapshotHash:f.session.pointer.snapshotHash,bindings:[]},[token.resourceId],undefined,token);runs.push(run);await run.prepare();const proof=c.proof(run.runId,token);expect(proof).toMatchObject({schema:2,appIds:[]});expect(f.runs.assertPrepared(run.runId).applicationScope).toEqual([]);expect(readClaudeSlot(f.store,f.snapshot.taskId)).toMatchObject({schema:2,current:{appIds:[]},preparation:null});c.assertRun(run.runId,proof);for(const p of f.snapshot.packages)for(const s of p.skills)expect(existsSync(s.projectionPath)).toBe(false);for(const ref of before)expect(await f.sessions.references(f.snapshot.taskId)).toContainEqual(ref);
 });
 it('rejects an old-format preparation token instead of silently upgrading an empty application handoff',async()=>{
  missing();const token=await c.prepareIndependent(f.snapshot.taskId),{schema:_,...old}=token;let failure:unknown;try{const accepted=await f.runs.reserveIndependent({taskId:f.snapshot.taskId,snapshotHash:f.session.pointer.snapshotHash,bindings:[]},[token.resourceId],undefined,old as never);runs.push(accepted);}catch(error){failure=error;}expect(failure).toMatchObject({code:'RESOURCE_RECOVERY_REQUIRED'});await c.cancel(token);
 });
 it('does not accept a rehashed schema1 slot containing an empty current view or drop its preparation lease',async()=>{
  missing();const token=await c.prepareIndependent(f.snapshot.taskId),id='claude-delivery-slot:'+f.snapshot.taskId,row=f.sqlite.prepare('SELECT plan_json FROM capability_resource_operations WHERE operation_id=?').get(id) as {plan_json:string},value=JSON.parse(row.plan_json);value.payload.schema=1;value.evidenceHash=digest(JSON.stringify(value.payload,Object.keys(value.payload).sort()));
  // Hash the same canonical payload,so rejection concerns the old format itself.
  value.evidenceHash=digest(canonicalSlot(value.payload));try{f.sqlite.prepare('UPDATE capability_resource_operations SET plan_json=? WHERE operation_id=?').run(JSON.stringify(value),id);expect(()=>readClaudeSlot(f.store,f.snapshot.taskId)).toThrow('待核验');expect(f.sqlite.prepare('SELECT state FROM capability_resource_leases WHERE lease_id=?').get(token.leaseId)).toEqual({state:'active'});}finally{f.sqlite.prepare('UPDATE capability_resource_operations SET plan_json=? WHERE operation_id=?').run(row.plan_json,id);}await c.cancel(token);
 });
''')
