add('agent-adapters.test.ts',"describe.skipIf(process.platform !== 'darwin' || process.arch !== 'arm64')('fixed adapter packages and actual complete Skill projection plans', () => {",'''
 it('plans explicit independent Codex standards and context without allowing an app bridge or silently accepting an ordinary empty scope',async()=>{
  const snapshot=f.plan('codex');await f.sessions.create(snapshot,f.home);const input=await f.request(snapshot),legacy=input.mcp.filter(m=>m.kind==='legacy-project-context'),safe={...input,independentCapabilities:true as const,applicationScope:[],mcp:legacy};expect(()=>f.adapters.plan(snapshot.adapterBinding.hash,{...input,applicationScope:[]})).toThrow();expect(()=>f.adapters.plan(snapshot.adapterBinding.hash,{...input,applicationScope:[],independentCapabilities:true})).toThrow();const plan=f.adapters.plan(snapshot.adapterBinding.hash,safe),flags=(parseToml(plan.args.find(a=>a.startsWith('skills.config='))!).skills as {config:{path:string;enabled:boolean}[]}).config;for(const p of snapshot.packages)for(const s of p.skills)expect(flags).toContainEqual({path:s.projectionPath,enabled:false});for(const s of snapshot.standardSkills)expect(flags).toContainEqual({path:s.projectionPath,enabled:true});expect(plan.args.join('\\n')).not.toContain('mcp_servers.'+snapshot.mcp.find(m=>m.kind==='applications')!.serverName);expect((await f.sessions.get(snapshot.taskId)).snapshot).toEqual(snapshot);
 });
''')
add('task-capability-launcher.test.ts',"describe('per-application availability does not withdraw healthy fixed tools',()=>{",'''
 it.each(['claude-code','codex'] as const)('keeps independent capabilities when only the application bridge runtime is unready: %s',async runner=>{
  const builtin=await selectBoth(),pack=builtin.retainedMetadata(builtin.packages.active('mail')!.packageHash),id='runtime:'+pack.manifest.runtime.hash;sqlite.prepare("UPDATE capability_resources SET state='recovery-required',integrity='invalid' WHERE resource_id=?").run(id);let started:Awaited<ReturnType<typeof create>>|undefined;
  try{started=await create(runner==='codex'?codexId:claudeId);const fixed=await managed.sessions.get(started.task.id),runtime=started.task.runtimeSnapshot!;expect(runtime.skills.map(s=>s.path)).toEqual(fixed.snapshot.standardSkills.map(s=>s.projectionPath));expect(runtime.skills.length).toBeGreaterThan(0);expect(runtime.mcp.map(m=>m.name)).toEqual(fixed.snapshot.mcp.filter(m=>m.kind==='legacy-project-context').map(m=>m.serverName));expect(managed.runs.assertActive(runtime.runId).applicationScope).toEqual([]);expect(sqlite.prepare('SELECT 1 FROM capability_lease_resources r JOIN capability_resource_leases l ON l.lease_id=r.lease_id WHERE l.owner_id=? AND r.resource_id=?').get(runtime.runId,id)).toBeUndefined();expect((await appTools().list(runtime.runId)).tools).toEqual([]);}finally{if(started){tasks.kill(started.task.id);await vi.waitFor(()=>expect(managed.runs.get(started!.task.runtimeSnapshot!.runId).state).toBe('stopped'));}}
 });
 it.each(['claude-code','codex'] as const)('does not widen an independent live run after same-hash app repair and restores all original capabilities only on stopped resume: %s',async runner=>{
  const builtin=await selectBoth(),initial=await create(runner==='codex'?codexId:claudeId);await stopForSwitchFixture(initial,runner);const original=await managed.sessions.get(initial.task.id),raw=sqlite.prepare('SELECT snapshot_json FROM capability_session_snapshots WHERE task_id=?').get(initial.task.id),source=new CapabilityBundleSource(resolve('out/capability-bundles'));for(const p of original.snapshot.packages)rmSync(join(support.store.root,builtin.retainedMetadata(p.packageHash).relativePath),{recursive:true});
  const partial=await tasks.open({taskId:initial.task.id});try{expect(managed.runs.assertActive(partial.task.runtimeSnapshot!.runId).applicationScope).toEqual([]);for(const p of original.snapshot.packages)await builtin.install(source,source.index.apps.find(a=>a.hash===p.packageHash)!);expect(managed.runs.assertActive(partial.task.runtimeSnapshot!.runId).applicationScope).toEqual([]);expect((await appTools().list(partial.task.runtimeSnapshot!.runId)).tools).toEqual([]);}finally{tasks.kill(initial.task.id);await vi.waitFor(()=>expect(managed.runs.get(partial.task.runtimeSnapshot!.runId).state).toBe('stopped'));}
  const full=await tasks.open({taskId:initial.task.id});try{expect(managed.runs.assertActive(full.task.runtimeSnapshot!.runId).applicationScope).toEqual(original.snapshot.packages.map(p=>p.appId));expect((await appTools().list(full.task.runtimeSnapshot!.runId)).tools).toHaveLength(17);expect(sqlite.prepare('SELECT snapshot_json FROM capability_session_snapshots WHERE task_id=?').get(initial.task.id)).toEqual(raw);}finally{tasks.kill(initial.task.id);await vi.waitFor(()=>expect(managed.runs.get(full.task.runtimeSnapshot!.runId).state).toBe('stopped'));}
 },30000);
 it.each(['claude-code','codex'] as const)('keeps original independent Skills while respecting current project MCP disablement after app loss: %s',async runner=>{
  const builtin=await selectBoth(),first=await create(runner==='codex'?codexId:claudeId);await stopForSwitchFixture(first,runner);const fixed=await managed.sessions.get(first.task.id);capabilities.setEnabled(projectId,MCP_CAPABILITY,false);for(const p of fixed.snapshot.packages)rmSync(join(support.store.root,builtin.retainedMetadata(p.packageHash).relativePath),{recursive:true});const started=await tasks.open({taskId:first.task.id});try{expect(started.task.runtimeSnapshot!.mcp).toEqual([]);expect(started.task.runtimeSnapshot!.skills.length).toBe(fixed.snapshot.standardSkills.length);expect(managed.runs.assertActive(started.task.runtimeSnapshot!.runId).applicationScope).toEqual([]);expect((await managed.sessions.get(first.task.id)).snapshot).toEqual(fixed.snapshot);const args=ptys.launches.at(-1)!.args;if(runner==='claude-code')expect(args).not.toContain('--mcp-config');else expect(args.join('\\n')).not.toContain('mcp_servers.');}finally{tasks.kill(first.task.id);await vi.waitFor(()=>expect(managed.runs.get(started.task.runtimeSnapshot!.runId).state).toBe('stopped'));}
 });
''')
